fn with_query(url: &str, key: &str, value: &str) -> String {
    let sep = if url.contains('?') { '&' } else { '?' };
    format!(
        "{}{}{}={}",
        url,
        sep,
        crate::runtime::escape_query(key),
        crate::runtime::escape_query(value)
    )
}

#[async_trait::async_trait]
impl TransportConn for LongpollConn {
    fn kind(&self) -> TransportKind {
        TransportKind::Longpoll
    }
    async fn send_json(&mut self, value: serde_json::Value) -> Result<(), RealtimeError> {
        let mut req = self.state.client.post(self.state.url.as_str()).json(&value);
        for (k, v) in &self.state.headers {
            req = req.header(k.as_str(), v.as_str());
        }
        let resp = req.send().await.map_err(|e| RealtimeError::Send(Error::Other(e.to_string())))?;
        if !resp.status().is_success() {
            return Err(RealtimeError::Send(Error::Other(format!("status {}", resp.status()))));
        }
        Ok(())
    }
    /// recv_json returns the next queued event, polling when the queue is empty.
    /// A failed or non-2xx poll is returned as an error (ResumableConnection backs off).
    async fn recv_json(&mut self) -> Result<serde_json::Value, RealtimeError> {
        loop {
            if let Some(ev) = self.state.pending_events.pop_front() {
                return Ok(ev);
            }
            let request_url = match &self.state.cursor {
                Some(c) => with_query(&self.state.url, "cursor", c),
                None => self.state.url.clone(),
            };
            let mut req = self.state.client.get(request_url.as_str()).timeout(POLL_TIMEOUT);
            for (k, v) in &self.state.headers {
                req = req.header(k.as_str(), v.as_str());
            }
            let resp = req.send().await.map_err(|e| RealtimeError::Recv(Error::Other(e.to_string())))?;
            if !resp.status().is_success() {
                return Err(RealtimeError::Recv(Error::Other(format!(
                    "longpoll status {}",
                    resp.status()
                ))));
            }
            let bytes = resp.bytes().await.map_err(|e| RealtimeError::Recv(Error::Other(e.to_string())))?;
            if bytes.is_empty() {
                continue;
            }
            match serde_json::from_slice::<serde_json::Value>(&bytes)
                .map_err(|e| RealtimeError::Recv(Error::Json(e)))?
            {
                serde_json::Value::Array(events) => self.state.pending_events.extend(events),
                serde_json::Value::Object(mut obj) => {
                    if let Some(c) = obj.get("cursor").and_then(|c| c.as_str()) {
                        self.state.cursor = Some(c.to_string());
                    }
                    if let Some(serde_json::Value::Array(events)) = obj.remove("events") {
                        self.state.pending_events.extend(events);
                    }
                }
                other => self.state.pending_events.push_back(other),
            }
        }
    }
    async fn close(&mut self) -> Result<(), RealtimeError> {
        /* no persistent connection to tear down */
        Ok(())
    }
}

