/// ResumableConnection is a typed, self-reconnecting realtime channel.
/// Send/Recv type parameters encode the message types flowing in each direction.
///
/// `recv` is cancel-safe with respect to the connection: if a `recv` future is
/// dropped mid-reconnect (`select!`, `timeout`), the next `recv` or `send`
/// reopens the chain instead of reporting the connection closed.
pub struct ResumableConnection<Send, Recv> {
    state: ConnectionState,
    url: String,
    opts: ResumableConnectionOpts,
    transport_opts: TransportOpts,
    transports: Vec<Box<dyn Transport>>,
    conn: Option<Box<dyn TransportConn>>,
    proven_index: Option<usize>,
    reconnect_attempts: u32,
    closed: bool,
    _send: PhantomData<Send>,
    _recv: PhantomData<Recv>,
}

impl<SendMsg, RecvMsg> ResumableConnection<SendMsg, RecvMsg>
where
    SendMsg: Serialize,
    RecvMsg: DeserializeOwned,
{
    /// connect tries each transport in order, memoizes the first that succeeds,
    /// and returns the active ResumableConnection.
    pub async fn connect(
        url: String,
        opts: ResumableConnectionOpts,
        transports: Vec<Box<dyn Transport>>,
    ) -> Result<Self, RealtimeError> {
        if transports.is_empty() {
            return Err(RealtimeError::Connect(Error::Other("no transports configured".into())));
        }
        let transport_opts = TransportOpts {
            reconnect_token: opts.reconnect_token.clone(),
            protocols: opts.protocols.clone(),
            last_event_id: opts.last_event_id.clone(),
            headers: opts.headers.clone(),
            http_client: opts.http_client.clone(),
            max_reconnect_attempts: opts.max_reconnect_attempts,
            reconnect_delay_ms: opts.reconnect_delay_ms,
        };
        let mut rc = ResumableConnection {
            state: ConnectionState::Connecting,
            url,
            opts,
            transport_opts,
            transports,
            conn: None,
            proven_index: None,
            reconnect_attempts: 0,
            closed: false,
            _send: PhantomData,
            _recv: PhantomData,
        };
        rc.open_chain().await?;
        Ok(rc)
    }

    /// connect_with_defaults builds the canonical transport chain
    /// `[WsTransport, SseTransport, LongpollTransport]` and calls [`Self::connect`].
    /// Convenience entry point for consumers that don't need a custom chain.
    pub async fn connect_with_defaults(
        url: String,
        opts: ResumableConnectionOpts,
    ) -> Result<Self, RealtimeError> {
        let transports: Vec<Box<dyn Transport>> = vec![
            Box::new(WsTransport),
            Box::new(SseTransport::default()),
            Box::new(LongpollTransport::default()),
        ];
        Self::connect(url, opts, transports).await
    }

    /// state returns the current connection lifecycle state.
    pub fn state(&self) -> &ConnectionState {
        &self.state
    }

    /// proven_transport returns the kind of the last successfully-opened transport.
    pub fn proven_transport(&self) -> Option<TransportKind> {
        self.proven_index.and_then(|i| self.transports.get(i)).map(|t| t.kind())
    }

    /// current_transport returns the kind of the currently-active transport.
    pub fn current_transport(&self) -> Option<TransportKind> {
        self.conn.as_ref().map(|c| c.kind())
    }

    /// send serialises a message and writes it to the active transport,
    /// reopening the chain first if a previous reconnect was interrupted.
    pub async fn send(&mut self, data: &SendMsg) -> Result<(), RealtimeError> {
        self.ensure_open().await?;
        let v = serde_json::to_value(data).map_err(|e| RealtimeError::Send(Error::Json(e)))?;
        let conn = self.conn.as_mut().ok_or(RealtimeError::Closed)?;
        conn.send_json(v).await
    }

    /// recv reads the next message, reconnecting with exponential backoff and
    /// jitter on transport failure. Gives up after `max_reconnect_attempts`
    /// consecutive failures and returns the last error.
    pub async fn recv(&mut self) -> Result<RecvMsg, RealtimeError> {
        loop {
            self.ensure_open().await?;
            let result = match self.conn.as_mut() {
                Some(conn) => conn.recv_json().await,
                None => continue,
            };
            match result {
                Ok(v) => {
                    self.reconnect_attempts = 0;
                    return serde_json::from_value(v).map_err(|e| RealtimeError::Recv(Error::Json(e)));
                }
                Err(err) => {
                    if self.closed {
                        return Err(RealtimeError::Closed);
                    }
                    self.state = ConnectionState::Reconnecting;
                    /* drop the dead conn + invalidate proven so the chain retries from the top */
                    if let Some(mut c) = self.conn.take() {
                        let _ = c.close().await;
                    }
                    self.proven_index = None;
                    if let Err(e) = self.reconnect(err).await {
                        self.state = ConnectionState::Disconnected;
                        return Err(e);
                    }
                }
            }
        }
    }

    /// close gracefully shuts down the connection; later calls return Closed.
    pub async fn close(&mut self) -> Result<(), RealtimeError> {
        self.closed = true;
        if let Some(mut c) = self.conn.take() {
            let _ = c.close().await;
        }
        self.state = ConnectionState::Disconnected;
        Ok(())
    }

    async fn ensure_open(&mut self) -> Result<(), RealtimeError> {
        if self.closed {
            return Err(RealtimeError::Closed);
        }
        if self.conn.is_some() {
            return Ok(());
        }
        /* a reconnect future was dropped mid-way: pick up where it left off */
        self.state = ConnectionState::Reconnecting;
        self.reconnect(RealtimeError::Closed).await
    }

    async fn reconnect(&mut self, mut last: RealtimeError) -> Result<(), RealtimeError> {
        let max_attempts = self.opts.max_reconnect_attempts.unwrap_or(5);
        loop {
            self.reconnect_attempts += 1;
            if max_attempts > 0 && self.reconnect_attempts > max_attempts {
                return Err(last);
            }
            tokio::time::sleep(self.backoff(self.reconnect_attempts)).await;
            match self.open_chain().await {
                Ok(()) => return Ok(()),
                Err(e) => last = e,
            }
        }
    }

    fn backoff(&self, attempt: u32) -> Duration {
        let base = Duration::from_millis(self.opts.reconnect_delay_ms.unwrap_or(1000));
        let mut d = base;
        for _ in 1..attempt {
            if d >= MAX_RECONNECT_DELAY {
                break;
            }
            d *= 2;
        }
        let d = d.min(MAX_RECONNECT_DELAY);
        /* jitter in [d/2, d] without a rand dependency */
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|t| t.subsec_nanos() as u64)
            .unwrap_or(0);
        let half = d.as_millis() as u64 / 2;
        Duration::from_millis(half + if half == 0 { 0 } else { nanos % (half + 1) })
    }

    async fn open_chain(&mut self) -> Result<(), RealtimeError> {
        let mut order: Vec<usize> = Vec::with_capacity(self.transports.len());
        if let Some(i) = self.proven_index {
            order.push(i);
        }
        order.extend((0..self.transports.len()).filter(|i| Some(*i) != self.proven_index));
        let mut last_err: Option<RealtimeError> = None;
        for i in order {
            let Some(t) = self.transports.get(i) else { continue };
            match tokio::time::timeout(OPEN_TIMEOUT, t.connect(&self.url, &self.transport_opts)).await {
                Ok(Ok(c)) => {
                    self.conn = Some(c);
                    self.proven_index = Some(i);
                    self.state = ConnectionState::Connected;
                    return Ok(());
                }
                Ok(Err(e)) => last_err = Some(e),
                Err(_) => last_err = Some(connect_err("transport open timed out")),
            }
        }
        Err(last_err.unwrap_or(RealtimeError::Connect(Error::Other("all transports failed".into()))))
    }
}

/// build_sse_state opens the stream; a non-2xx status or a non-event-stream
/// content type is a connect error, so the chain moves on.
async fn build_sse_state(
    url: String,
    http_client: reqwest::Client,
    opts: &TransportOpts,
) -> Result<SseState, RealtimeError> {
    let mut req_builder = http_client.get(url.as_str()).header("Accept", "text/event-stream");
    if let Some(ref last_event_id) = opts.last_event_id {
        req_builder = req_builder.header("Last-Event-ID", last_event_id.as_str());
    }
    for (k, v) in &opts.headers {
        req_builder = req_builder.header(k.as_str(), v.as_str());
    }
    if !opts.headers.keys().any(|k| k.eq_ignore_ascii_case("x-request-id")) {
        req_builder = req_builder.header("x-request-id", uuid::Uuid::new_v4().to_string());
    }
    let resp = req_builder.send().await.map_err(connect_err)?;
    if !resp.status().is_success() {
        return Err(connect_err(format!("sse status {}", resp.status())));
    }
    let is_event_stream = resp
        .headers()
        .get(reqwest::header::CONTENT_TYPE)
        .and_then(|v| v.to_str().ok())
        .map(|v| v.to_ascii_lowercase().starts_with("text/event-stream"))
        .unwrap_or(false);
    if !is_event_stream {
        return Err(connect_err("sse response is not text/event-stream"));
    }
    let byte_stream: ByteStream = Box::pin(resp.bytes_stream());
    Ok(SseState {
        byte_stream,
        last_event_id: opts.last_event_id.clone(),
        retry_hint_ms: opts.reconnect_delay_ms.unwrap_or(1000),
        parser: SseParser::new(),
        pending: VecDeque::new(),
        http_client,
        url,
        extra_headers: opts.headers.clone(),
    })
}
